export const DEFAULT_QUOTE_TERMS = 'You may cancel free of charge before paying the advance. After advance payment, contact the shop before cancelling; any applicable deduction and refund must be explained and agreed before payment. If the shop cannot fulfil the accepted order, the advance will be refunded in full. No bargaining or change-of-mind returns after fulfilment. Incorrect or defective items can be reviewed with an unboxing video or other suitable evidence. Applicable consumer rights remain unaffected.';
export function orderStatus(o,now=Date.now()) {return ['quoted','agreed'].includes(o.status)&&Date.parse(o.quote_expires_at)<=now?'Quote expired':({pending:'Awaiting shop review',quoted:'Quote ready',agreed:'Quote agreed · advance unpaid',rejected:'Rejected by shop',cancelled:'Cancelled'})[o.status]||o.status;}
export const quoteExpiryISO = value => new Date(value+':00+05:30').toISOString();
export function createOrderUI({auth,modal,esc,toast,getBag,clearBag,refreshBag,preferredName}){
 const $=s=>document.querySelector(s),money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(n));
 const time=s=>new Date(s).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'})+' IST';
 const localDate=ms=>new Date(ms+19800000).toISOString().slice(0,16);
 const api=auth.orders;let listing={page:1,admin:false,status:''},generation=0;
 const authorised=uid=>auth.state.user?.id===uid;
 async function run(form,fn){const buttons=[...form.querySelectorAll('button,input,select,textarea')];buttons.forEach(b=>b.disabled=true);try{await fn()}catch(e){const error=form.querySelector('[role="alert"]');if(error)error.textContent=e.message;else toast(e.message)}finally{buttons.forEach(b=>b.disabled=false)}}
 const requestTerms='<p>A request is not a confirmed sale or stock reservation. The displayed amount estimates jewellery only; the shop will quote GST, delivery charges and an expected date after checking availability. No payment is taken now.</p><p>After shop acceptance, review the final quote and its expiry. A 20% advance will be needed to confirm, with 80% payable on delivery or at pickup. You may cancel before paying without charge. Payment collection is not enabled yet.</p>';
 async function checkout(){
  const uid=auth.state.user?.id;if(!uid)return;
  try{await refreshBag();if(!authorised(uid))return;}catch(e){toast(e.message);return}
  const bag=getBag();if(!bag.length){toast('Your bag is empty.');return}
  modal('Request your jewellery',`<p>Choose how you would like to receive your jewellery.</p><div class="price-lines">${bag.map(p=>`<div><span>${esc(p.name)} × ${p.qty}</span><strong>${money(p.estimate*p.qty)}</strong></div>`).join('')}<div class="total"><span>Estimated jewellery amount</span><strong>${money(bag.reduce((s,p)=>s+p.estimate*p.qty,0))}</strong></div></div><p>GST and delivery are not included yet. Your saved estimate uses the latest verified rates when you submit.</p><form id="requestForm"><div class="form-grid"><label class="full">Receive your order<select name="method"><option value="delivery">Home delivery</option><option value="pickup">Shop pickup</option></select></label><label>Name<input name="name" maxlength="80" autocomplete="name" value="${esc(preferredName())}" required></label><label>Mobile number<input name="phone" type="tel" autocomplete="tel" placeholder="+91 98407 63243" required maxlength="18"></label><label class="full">Full address<textarea name="address" minlength="10" maxlength="500" autocomplete="street-address" required></textarea></label><label>City<input name="city" maxlength="80" minlength="2" autocomplete="address-level2" required></label><label>State<input name="state" maxlength="80" minlength="2" autocomplete="address-level1" required></label><label>PIN code<input name="pincode" inputmode="numeric" pattern="[1-9][0-9]{5}" maxlength="6" autocomplete="postal-code" required></label></div><p>Your address is required for both delivery and pickup. It is shared only with you and the shop administrator for this request.</p><details class="order-terms"><summary>Request, payment and cancellation terms</summary>${requestTerms}</details><label class="checks"><input name="terms" type="checkbox" required><span>I have read the terms and understand this is an order request, with no payment today.</span></label><p role="alert" class="auth-error"></p><button class="primary" type="submit">Place order request · No payment</button></form>`);
  const form=$('#requestForm');form.onsubmit=e=>{e.preventDefault();const f=new FormData(form);let phone=String(f.get('phone')).replace(/[\s()-]/g,'');if(/^[6-9]\d{9}$/.test(phone))phone='+91'+phone;if(/^91[6-9]\d{9}$/.test(phone))phone='+'+phone;if(!/^\+91[6-9]\d{9}$/.test(phone)){form.querySelector('[role="alert"]').textContent='Enter a valid Indian mobile number.';return;}
   const items=bag.map(p=>({id:p.id,qty:p.qty}));const storageKey='lk-request-'+uid+'-'+JSON.stringify(items);let key;try{key=sessionStorage.getItem(storageKey);if(!key){key=crypto.randomUUID();sessionStorage.setItem(storageKey,key)}}catch{key=form.dataset.key||crypto.randomUUID();form.dataset.key=key}
   run(form,async()=>{const id=await api.submit({p_key:key,p_contact:{name:f.get('name'),phone,address:f.get('address'),city:f.get('city'),state:f.get('state'),pincode:f.get('pincode')},p_method:f.get('method'),p_items:items,p_terms:f.get('terms')==='on'});if(!authorised(uid))return;try{sessionStorage.removeItem(storageKey)}catch{}clearBag();listing={page:1,admin:false,status:''};await detail(id);toast('Request sent to L K Jewellers. No payment taken.');});
  };
 }
 async function list({admin=false,page=1,status=''}={}){
  const uid=auth.state.user?.id;if(!uid||admin&&!auth.state.admin)return;const attempt=++generation;listing={admin,page,status};modal(admin?'Shop order requests':'Your order requests','<p>Loading requests…</p>');
  try{const result=await api.list({...listing,userId:uid});if(!authorised(uid)||attempt!==generation||!$('#modal').open)return;
   modal(admin?'Shop order requests':'Your order requests',`<p>${admin?'Review availability, accept with a final quote, or reject with a reason.':'Requests and quotes are saved to your account. Check here for the shop’s response.'}</p><div class="order-toolbar"><label>Status<select id="orderFilter"><option value="">All requests</option>${[['pending','Awaiting review'],['quoted','Quoted'],['agreed','Quote agreed'],['rejected','Rejected'],['cancelled','Cancelled']].map(([v,t])=>`<option value="${v}" ${status===v?'selected':''}>${t}</option>`).join('')}</select></label><button class="secondary" id="reloadOrders">Refresh</button></div><div class="order-list">${result.items.map(o=>`<button class="order-card" data-order="${o.id}"><strong>${esc(orderStatus(o))}</strong><span>${esc(admin?o.contact.name:'Request #'+o.id.slice(0,8))} · ${o.fulfilment==='pickup'?'Shop pickup':'Home delivery'}</span><small>${esc(time(o.created_at))}</small><span>Estimated jewellery: ${money(o.estimated_subtotal)} →</span></button>`).join('')||'<p>No requests in this view.</p>'}</div><div class="pagination"><button class="secondary" id="orderPrev" ${page<=1?'disabled':''}>← Previous</button><span>Page ${page} of ${Math.max(1,Math.ceil(result.count/12))}</span><button class="secondary" id="orderNext" ${page*12>=result.count?'disabled':''}>Next →</button></div>`);
   $('#reloadOrders').onclick=()=>list(listing);$('#orderFilter').onchange=e=>list({...listing,page:1,status:e.target.value});$('#orderPrev').onclick=()=>list({...listing,page:page-1});$('#orderNext').onclick=()=>list({...listing,page:page+1});document.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>detail(b.dataset.order));
  }catch(e){if(authorised(uid)&&attempt===generation){modal('Could not load requests',`<p>${esc(e.message)}</p><button class="secondary" id="retryOrders">Retry</button>`);$('#retryOrders').onclick=()=>list(listing)}}
 }
 async function detail(id){
  const uid=auth.state.user?.id;if(!uid)return;const attempt=++generation;modal('Order request','<p>Loading request…</p>');
  try{const {order:o,quotes}=await api.detail(id);if(!authorised(uid)||attempt!==generation||!$('#modal').open)return;
   const q=quotes.find(q=>q.id===o.quote_id),admin=auth.state.admin&&listing.admin,own=o.customer_id===uid,active=['pending','quoted','agreed'].includes(o.status),expired=q&&Date.parse(q.expires_at)<=Date.now();
   modal('Request #'+o.id.slice(0,8),`<button class="text-button" id="backOrders">← Back to requests</button><div class="eyebrow">${esc(orderStatus(o))}</div><p>${o.fulfilment==='pickup'?'Shop pickup':'Home delivery'} · Requested ${esc(time(o.created_at))}</p><div class="price-lines">${o.items.map(i=>`<div><span>${esc(i.name)} × ${i.qty}<small>${esc(i.purity)} · ${i.weight} g each</small></span><span>${money(i.unit_estimate*i.qty)}</span></div>`).join('')}<div><strong>Original jewellery estimate</strong><strong>${money(o.estimated_subtotal)}</strong></div></div><h3>Contact & address</h3><p>${esc(o.contact.name)} · ${esc(o.contact.phone)}<br>${esc(o.contact.address)}<br>${esc(o.contact.city)}, ${esc(o.contact.state)} ${esc(o.contact.pincode)}</p>${o.note?`<div class="notice">${esc(o.note)}</div>`:''}${q?quoteHTML(q,o):'<div class="notice">The shop will check stock and provide the final amount, delivery charge and expected date. No payment is due now.</div>'}${q&&own&&o.status==='quoted'&&!expired?'<form id="agreeQuote"><label class="checks"><input type="checkbox" required><span>I agree to this final quote, validity period and cancellation/refund terms.</span></label><p role="alert" class="auth-error"></p><button class="primary">Agree to quote</button></form>':''}${q&&active?'<p class="notice">Online advance payment is not available yet. No advance has been collected, and this request is not payment-confirmed.</p><button class="secondary" disabled>Pay 20% advance · Coming soon</button>':''}${admin&&active?'<div class="admin-tabs"><button class="primary" id="issueQuote">'+(q?'Revise / renew quote':'Accept & prepare quote')+'</button><button class="secondary" id="rejectOrder">Reject request</button></div>':''}${own&&active?'<p><button class="text-button danger" id="cancelOrder">Cancel request before payment</button></p>':''}${quotes.length>1?`<details><summary>Previous quotes (${quotes.length-1})</summary>${quotes.filter(x=>x.id!==o.quote_id).map(x=>`<p>${esc(time(x.created_at))} · ${money(x.total)} · Superseded</p>`).join('')}</details>`:''}`);
   $('#backOrders').onclick=()=>list(listing);
   if($('#agreeQuote'))$('#agreeQuote').onsubmit=e=>{e.preventDefault();run(e.currentTarget,async()=>{await api.respond({p_id:id,p_version:o.version,p_action:'agree',p_note:''});if(authorised(uid))await detail(id)})};
   if($('#issueQuote'))$('#issueQuote').onclick=()=>quoteForm(o,q);
   if($('#rejectOrder'))$('#rejectOrder').onclick=()=>decision(o,'reject');
   if($('#cancelOrder'))$('#cancelOrder').onclick=()=>decision(o,'cancel');
  }catch(e){if(authorised(uid)&&attempt===generation){modal('Could not load request',`<p>${esc(e.message)}</p><button class="secondary" id="retryDetail">Retry</button>`);$('#retryDetail').onclick=()=>detail(id)}}
 }
 function quoteHTML(q,o){return `<h3>Shop’s final quote</h3><div class="price-lines"><div><span>Jewellery including shop charge</span><strong>${money(q.jewellery_amount)}</strong></div><div><span>GST</span><strong>${money(q.gst_amount)}</strong></div><div><span>${o.fulfilment==='pickup'?'Shop pickup':'Delivery'}</span><strong>${money(q.delivery_amount)}</strong></div><div class="total"><span>Final total</span><strong>${money(q.total)}</strong></div><div><span>20% advance</span><strong>${money(q.advance_amount)}</strong></div><div><span>80% due ${o.fulfilment==='pickup'?'at pickup':'upon delivery'}</span><strong>${money(q.balance_amount)}</strong></div></div><p><strong>Valid until:</strong> ${esc(time(q.expires_at))}<br><strong>Expected ${o.fulfilment==='pickup'?'pickup':'delivery'}:</strong> ${esc(q.expected_date)}</p><p>The expected date applies after timely advance payment. An unpaid expired quote requires a new shop quote; rates and availability may change.</p><details open class="order-terms"><summary>Cancellation & refund terms</summary><p class="preserve-lines">${esc(q.terms)}</p></details>`;}
 function decision(o,action){modal(action==='reject'?'Reject this request?':'Cancel this request?',`<p>${action==='reject'?'Explain why this request cannot be accepted. The customer will see your reason.':'No payment has been collected. Cancelling will release any stock held for this quote.'}</p><form id="decisionForm">${action==='reject'?'<label>Reason<textarea name="note" required minlength="3" maxlength="1000"></textarea></label>':''}<p role="alert" class="auth-error"></p><div class="form-actions"><button type="button" class="secondary" id="keepRequest">Keep request</button><button class="primary" type="submit">${action==='reject'?'Reject request':'Confirm cancellation'}</button></div></form>`);$('#keepRequest').onclick=()=>detail(o.id);$('#decisionForm').onsubmit=e=>{e.preventDefault();const note=new FormData(e.currentTarget).get('note')||'';run(e.currentTarget,async()=>{await api.respond({p_id:o.id,p_version:o.version,p_action:action,p_note:note});await detail(o.id)})};}
 function quoteForm(o,q){if(!auth.state.admin)return;modal('Accept & issue final quote',`<p>Check physical stock first. This quote holds the requested quantities until expiry. Set stock quantities under Edit jewellery before accepting.</p><p>${o.items.map(i=>`${esc(i.name)} × ${i.qty}`).join('<br>')}</p><form id="quoteForm"><div class="form-grid"><label>Jewellery incl. shop charge (₹)<input name="jewellery_amount" type="number" min="0.01" max="100000000" step="0.01" value="${q?.jewellery_amount||o.estimated_subtotal}" required></label><label>GST amount (₹)<input name="gst_amount" type="number" min="0" max="100000000" step="0.01" value="${q?.gst_amount??''}" required></label><label>Delivery charge (₹)<input name="delivery_amount" type="number" min="0" max="1000000" step="0.01" value="${o.fulfilment==='pickup'?0:q?.delivery_amount??''}" ${o.fulfilment==='pickup'?'readonly':''} required></label><label>Expected ${o.fulfilment==='pickup'?'pickup':'delivery'} date<input name="expected_date" type="date" min="${localDate(Date.now()).slice(0,10)}" value="${q?.expected_date||''}" required></label><label class="full">Quote valid until (Indian Standard Time)<input name="expires" type="datetime-local" value="${localDate(Date.now()+86400000)}" required></label><label class="full">Cancellation & refund terms<textarea name="terms" minlength="20" maxlength="3000" rows="8" required>${esc(q?.terms||DEFAULT_QUOTE_TERMS)}</textarea></label></div><div id="quoteTotals" class="notice"></div><p>20% is the advance; 80% is due on ${o.fulfilment==='pickup'?'pickup':'delivery'}. Payment collection is not connected yet. Revising a quote requires the customer to agree again.</p><p role="alert" class="auth-error"></p><div class="form-actions"><button class="secondary" type="button" id="backRequest">Back</button><button class="primary" type="submit">Accept & issue quote</button></div></form>`);
  const form=$('#quoteForm');const totals=()=>{const f=new FormData(form),total=['jewellery_amount','gst_amount','delivery_amount'].reduce((sum,k)=>sum+Number(f.get(k)||0),0),advance=Math.round(total*20)/100;$('#quoteTotals').textContent=`Final total ${money(total)} · 20% advance ${money(advance)} · Balance ${money(total-advance)}`};form.oninput=totals;totals();$('#backRequest').onclick=()=>detail(o.id);
  form.onsubmit=e=>{e.preventDefault();const f=new FormData(form);const quote={jewellery_amount:Number(f.get('jewellery_amount')),gst_amount:Number(f.get('gst_amount')),delivery_amount:Number(f.get('delivery_amount')),expected_date:f.get('expected_date'),expires_at:quoteExpiryISO(f.get('expires')),terms:f.get('terms')};run(form,async()=>{await api.quote({p_id:o.id,p_version:o.version,p_quote:quote});await detail(o.id);toast('Final quote issued. No payment has been collected.')})};
 }
 return {checkout,list,detail};
}
